576	/* P1-9：目标路径已存在 → 自动改名「原名 (n).ext」去重 */
577	static void files_unique_dst(const char *src_name, char *dst, int dst_size)
578	{
579	    struct stat st;
580	    if (stat(dst, &st) != 0) return;   /* 无冲突，直接用原名 */
581	
582	    /* 拆扩展名：base + ext（.txt/.mp3/…，目录无扩展） */
583	    char base[256], ext[32] = "";
584	    const char *dot = strrchr(src_name, '.');
585	    if (dot && dot != src_name) {
586	        int bl = (int)(dot - src_name);
587	        if (bl >= (int)sizeof(base)) bl = (int)sizeof(base) - 1;
588	        memcpy(base, src_name, bl); base[bl] = '\0';
589	        snprintf(ext, sizeof(ext), "%s", dot);
590	    } else {
591	        snprintf(base, sizeof(base), "%s", src_name);
592	    }
593	
594	    for (int k = 1; k < 1000; k++) {
595	        if (ext[0])
596	            snprintf(dst, dst_size, "%s/%s (%d)%s", files_cur_path, base, k, ext);
597	        else
598	            snprintf(dst, dst_size, "%s/%s (%d)", files_cur_path, base, k);
599	        if (stat(dst, &st) != 0) return;   /* 找到可用名 */
600	    }
601	}
