603	/* 粘贴核心：复制/剪贴 → 当前目录（剪贴成功清空剪贴板） */
604	static void files_clip_paste(void)
605	{
606	    if (clip_count == 0) return;
607	    int n = 0;
608	    int renamed = 0;
609	    for (int i = 0; i < clip_count; i++) {
610	        const char *name = strrchr(clip_paths[i], '/'); name = name ? name + 1 : clip_paths[i];
611	        char dst[512]; snprintf(dst, sizeof(dst), "%s/%s", files_cur_path, name);
612	        if (strcmp(dst, clip_paths[i]) == 0) continue;
613	        int had_conflict = (stat(dst, &(struct stat){0}) == 0);
614	        files_unique_dst(name, dst, sizeof(dst));
615	        if (had_conflict) renamed++;
616	        if (clip_op_cut) rename(clip_paths[i], dst);
617	        else { char cmd[1024]; snprintf(cmd, sizeof(cmd), "cp -r \"%s\" \"%s\"", clip_paths[i], dst); system(cmd); }
618	        n++;
619	    }
620	    clip_count = 0; clip_op_cut = 0;
621	    files_scan_dir(files_cur_path); files_refresh_list();
622	    if (files_sel_paste_lbl)
623	        lv_obj_set_style_text_color(files_sel_paste_lbl, lv_color_hex(0xC6C6C8), 0);
624	    if (n > 0) {
625	        char msg[64];
626	        if (renamed > 0)
627	            snprintf(msg, sizeof(msg), "已粘贴 %d 项（%d 项重名已改名）", n, renamed);
628	        else
629	            snprintf(msg, sizeof(msg), "已粘贴 %d 项", n);
630	        files_toast_show(msg);
631	    }
632	}
