806	/* 打开文件（.txt → Books 阅读器；.mp3/.wav → Music 播放；其他 → toast 提示） */
807	static void files_open_file(const char *path, int type)
808	{
809	    if (type == FILE_TYPE_TXT) {
810	        for (uint32_t i = 0; i < dm_book_count; i++)
811	            if (strcmp(dm_book_paths[i], path) == 0) { book_open_reader(i); return; }
812	        if (dm_book_count < DM_MAX_BOOKS) {
813	            strncpy(dm_book_paths[dm_book_count], path, sizeof(dm_book_paths[0]) - 1);
814	            const char *name = strrchr(path, '/'); name = name ? name + 1 : path;
815	            const char *dot = strrchr(name, '.');
816	            int len = dot ? (int)(dot - name) : strlen(name);
817	            snprintf(dm_book_titles[dm_book_count], sizeof(dm_book_titles[0]), "%.*s", len, name);
818	            book_open_reader(dm_book_count); dm_book_count++;
819	        }
820	    } else if (type == FILE_TYPE_MP3) {
821	        /* P1-7：接入音乐播放核心（追加到 dm_tracks 尾部 → music_play） */
822	        if (dm_track_count < DM_MAX_TRACKS) {
823	            strncpy(dm_tracks[dm_track_count].path, path, sizeof(dm_tracks[0].path) - 1);
824	            const char *name = strrchr(path, '/'); name = name ? name + 1 : path;
825	            const char *dot = strrchr(name, '.');
826	            int len = dot ? (int)(dot - name) : strlen(name);
827	            snprintf(dm_tracks[dm_track_count].title, sizeof(dm_tracks[0].title), "%.*s", len, name);
828	            dm_tracks[dm_track_count].length = 0;
829	            dm_track_count++;
830	            music_play(dm_track_count - 1);
831	            files_toast_show("正在播放");
832	        } else {
833	            files_toast_show("播放列表已满");
834	        }
835	    } else {
836	        /* IMG / OTHER：暂无查看器 → 提示反馈（P1-7 消灭交互死区） */
837	        files_toast_show("暂不支持打开此类文件");
838	    }
839	}
