847	/* 操作栏"新建文件夹"：固定名 NewFolder，已存在则自动加序号去重 */
848	static void files_cb_sel_newfolder(lv_event_t *e)
849	{
850	    (void)e;
851	    char dir[512];
852	    snprintf(dir, sizeof(dir), "%s/NewFolder", files_cur_path);
853	    struct stat st;
854	    for (int k = 1; stat(dir, &st) == 0; k++)   /* 同名已存在 → NewFolder1/2/… */
855	        snprintf(dir, sizeof(dir), "%s/NewFolder%d", files_cur_path, k);
856	    char cmd[576];
857	    snprintf(cmd, sizeof(cmd), "mkdir -p \"%s\"", dir);
858	    system(cmd);
859	    files_scan_dir(files_cur_path); files_refresh_list();
860	    files_toast_show("已创建文件夹");
861	}
