863	/* 返回上级（选择模式下=取消选择） */
864	static void files_go_up(void)
865	{
866	    if (files_select_mode) { files_exit_select_mode(); return; }
867	    /* 已到根目录 → 再按一次退出子页 */
868	    if (strcmp(files_cur_path, "/") == 0 || strcmp(files_cur_path, "/sdcard") == 0) {
869	        close_subpage();
870	        return;
871	    }
872	    char *last = strrchr(files_cur_path, '/');
873	    if (last && last != files_cur_path) *last = '\0';
874	    else { files_cur_path[0] = '/'; files_cur_path[1] = '\0'; }
875	    files_scan_dir(files_cur_path); files_refresh_list(); files_update_breadcrumb();
876	}
