118	/* 根据扩展名判断文件类型 */
119	static int file_type_from_name(const char *name)
120	{
121	    const char *dot = strrchr(name, '.');
122	    if (!dot) return FILE_TYPE_OTHER;
123	    if (strcasecmp(dot, ".txt") == 0) return FILE_TYPE_TXT;
124	    if (strcasecmp(dot, ".mp3") == 0 || strcasecmp(dot, ".wav") == 0) return FILE_TYPE_MP3;
125	    if (strcasecmp(dot, ".jpg") == 0 || strcasecmp(dot, ".png") == 0) return FILE_TYPE_IMG;
126	    return FILE_TYPE_OTHER;
127	}
