129	/* 扫描目录 */
130	static void files_scan_dir(const char *path)
131	{
132	    DIR *dir = opendir(path);
133	    if (!dir) { files_count = 0; return; }
134	
135	    files_count = 0;
136	    struct dirent *ent;
137	    while ((ent = readdir(dir)) != NULL && files_count < FILES_MAX_ENTRIES) {
138	        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;
139	
140	        char full[256];
141	        snprintf(full, sizeof(full), "%s/%s", path, ent->d_name);
142	
143	        struct stat st;
144	        if (stat(full, &st) != 0) continue;
145	
146	        int type = S_ISDIR(st.st_mode) ? FILE_TYPE_DIR : file_type_from_name(ent->d_name);
147	
148	        strncpy(files_paths[files_count], full, sizeof(files_paths[0]) - 1);
149	        strncpy(files_names[files_count], ent->d_name, sizeof(files_names[0]) - 1);
150	        files_types[files_count] = type;
151	        files_sizes[files_count] = S_ISDIR(st.st_mode) ? 0 : (long)st.st_size;
152	        files_selected[files_count] = 0;
153	        files_count++;
154	    }
155	    closedir(dir);
156	
157	    /* 排序：目录在前、按名称升序（安卓文件管理器默认行为） */
158	    for (uint32_t i = 1; i < files_count; i++) {
159	        uint32_t j = i;
160	        while (j > 0) {
161	            int a_dir = (files_types[j - 1] == FILE_TYPE_DIR);
162	            int b_dir = (files_types[j] == FILE_TYPE_DIR);
163	            int swap = 0;
164	            if (a_dir != b_dir)            swap = b_dir;          /* 目录优先 */
165	            else if (strcmp(files_names[j - 1], files_names[j]) > 0) swap = 1; /* 名称升序 */
166	            if (!swap) break;
167	
168	            char tmp_p[256], tmp_n[64];
169	            int  tmp_t; long tmp_s;
170	            strcpy(tmp_p, files_paths[j - 1]);   strcpy(files_paths[j - 1], files_paths[j]);   strcpy(files_paths[j], tmp_p);
171	            strcpy(tmp_n, files_names[j - 1]);   strcpy(files_names[j - 1], files_names[j]);   strcpy(files_names[j], tmp_n);
172	            tmp_t = files_types[j - 1];          files_types[j - 1] = files_types[j];          files_types[j] = tmp_t;
173	            tmp_s = files_sizes[j - 1];          files_sizes[j - 1] = files_sizes[j];          files_sizes[j] = tmp_s;
174	            j--;
175	        }
176	    }
177	}
