/* ================================================================
 * BIG CLOCK — upper area, NO transform scaling
 * ================================================================ */

/* 2026-08-11：点击 hero 时钟 → 手动触发一轮天气 fetch（fetch 成功后
 * dm_weather_fetch 内部会用 HTTP Date 头 settimeofday 对时，worker
 * 线程 ≤5s 完成，时钟即刻跳变）。按压效果见 create_big_clock。 */
static void weather_kick_fetch(void);   /* 定义在 weather_fetch_worker 后 */
static void clock_click_cb(lv_event_t *e)
{
    (void)e;
    LV_LOG_USER("Clock clicked: manual time sync");
    weather_kick_fetch();
}

static void create_big_clock(lv_obj_t *parent)
{
    /* Clock container: column, centered content */
    lv_obj_t *clk_cont = make_clean_cont(parent);
    lv_obj_set_size(clk_cont, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(clk_cont, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(clk_cont, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(clk_cont, 8, 0);

    /* 2026-08-11：hero 时钟可点击 → 手动对时（clock_click_cb 触发一轮
     * 天气 fetch，fetch 成功即 HTTP Date 头 settimeofday）。按压效果
     * 抄天气卡观感：按下轻微放大，松开恢复。 */
    lv_obj_add_flag(clk_cont, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(clk_cont, clock_click_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_set_style_transform_width(clk_cont, 3, LV_STATE_PRESSED);
    lv_obj_set_style_transform_height(clk_cont, 3, LV_STATE_PRESSED);

    /* Big time — native 48px, no scaling, crisp rendering */
    clock_big_label = lv_label_create(clk_cont);
    lv_label_set_text(clock_big_label, "00:00");
    lv_obj_set_style_text_font(clock_big_label, FONT_TITLE, 0);
    lv_obj_set_style_text_color(clock_big_label, lv_color_hex(COL_TEXT), 0);
    lv_obj_set_style_text_letter_space(clock_big_label, 8, 0);

    /* Date — FONT_LABEL below clock (was caption, too small on 8") */
    clock_date_label = lv_label_create(clk_cont);
    lv_label_set_text(clock_date_label, "---");
    lv_obj_set_style_text_font(clock_date_label, FONT_LABEL, 0);
    lv_obj_set_style_text_color(clock_date_label, lv_color_hex(COL_TEXT), 0);
    lv_obj_set_style_text_letter_space(clock_date_label, 2, 0);
}

